'use strict';
// Two-table audit workflow: comparison setup and result review are separate operations.
const aswBase={workbench,configPanel,twMountPreview,mappingEditor,handleAction,modalContent,closeModal,resultContent,exportRows,doExport,configurationFragment};
const aswView={panel:'materials',query:'',page:1,size:20,editorTab:'fields',editorQuery:'',editorPage:1,editorSize:15};
const aswResultViews=new Map();
function aswActive(){return state.view==='tool'&&state.toolId==='association';}
function aswPreparing(){return aswActive()&&!currentTask();}
function aswConfig(){return currentTask()?.config||ws().config;}
function aswData(){return currentTask()||ws();}
function aswText(v){if(v===null||v===undefined||v==='')return '未提供';return typeof v==='object'?JSON.stringify(v):String(v);}
function aswTabs(items,current,action,attr='tab'){return '<nav class="asw-tabs" role="tablist">'+items.map(([key,name])=>'<button role="tab" class="'+(current===key?'active':'')+'" aria-selected="'+(current===key)+'" data-action="'+action+'" data-'+attr+'="'+key+'">'+name+'</button>').join('')+'</nav>';}
function aswPrompt(c,locked){const s=c.stages.compare;return '<section class="pg-stage-card asw-prompt" data-pg-stage-card="compare"><div><label class="pg-select-label"><span>'+(locked?'本次提示词':'比较提示词')+'</span>'+pgSelect('association','compare',s,'data-pg-prompt="compare" '+(locked?'disabled':''))+'</label>'+B(locked?'查看提示词':'编辑提示词','aw-prompt','sm','data-stage="compare"')+'</div></section>';}
function aswSourceCard(slot,i){const w=aswData(),d=file(w['table'+slot]),locked=!!currentTask();return '<section class="asw-source-card"><div class="asw-source-title"><span>表'+(i?'二':'一')+'</span><strong>'+(i?'对照台账':'待查台账')+'</strong></div><label class="field"><span>业务名称</span><input data-work="table'+slot+'Name" aria-label="表'+slot+'业务名称" maxlength="80" value="'+E(w['table'+slot+'Name']||'')+'" '+(locked?'readonly':'')+'></label>'+(d?'<button class="asw-source-file" data-action="source" data-id="'+E(d.id)+'">'+ficon(d)+'<span>'+E(d.name)+'</span></button><p class="asw-source-meta">'+(Array.isArray(d.rows)?'<strong>'+d.rows.length+'</strong> 条记录 · ':'')+'<strong>'+(d.columns?.length||0)+'</strong> 个表头</p>':'<p class="asw-empty-source">选择 Excel 或 CSV 台账。</p>')+(!locked?'<div class="asw-source-actions">'+B(d?'更换台账':'选择台账','pick-table','soft sm','data-slot="'+slot+'"')+(d?B('移出','remove-table','ghost sm','data-slot="'+slot+'"'):'')+'</div>':'')+'</section>';}
function aswMaterials(){return '<aside class="asw-materials"><div class="asw-panel-head"><h2><span class="tw-step">Step 1</span> 选择两张台账</h2></div><p class="asw-intro">先选待查台账，再选用于核对的另一张台账。</p><div class="asw-source-scroll">'+['A','B'].map(aswSourceCard).join('')+'</div><div class="asw-scope">已选 <strong>'+[ws().tableA,ws().tableB].filter(Boolean).length+'</strong> / 2 张台账</div></aside>';}
function aswFieldRows(g=aswConfig().association,editor=false){const q=(editor?aswView.editorQuery:aswView.query).toLowerCase().trim(),size=editor?aswView.editorSize:aswView.size,entries=g.rows.map((r,index)=>({r,index})).filter(({r})=>[r.name,r.a,r.b,r.rule].join(' ').toLowerCase().includes(q)),pages=Math.max(1,Math.ceil(entries.length/size)),key=editor?'editorPage':'page';aswView[key]=Math.max(1,Math.min(aswView[key],pages));const page=aswView[key],locked=!!currentTask();return '<div class="asw-table-scroll"><table class="asw-table asw-field-table"><thead><tr><th>比较内容</th><th>表一字段</th><th>表二字段</th><th>比较方式 / 权重</th><th>操作</th></tr></thead><tbody>'+entries.slice((page-1)*size,page*size).map(({r,index})=>'<tr><td><strong>'+E(r.name||'未命名字段')+'</strong></td><td>'+E(r.a||'未选择')+'</td><td>'+E(r.b||'未选择')+'</td><td>'+E(COMPARE_TYPES.find(t=>t[0]===r.type)?.[1]||r.type)+'<small>权重 '+E(r.weight)+'</small></td><td>'+A(editor?(locked?'查看':'编辑'):'查看规则',editor?'asw-edit-field':'asw-view-field','data-index="'+index+'"')+'</td></tr>').join('')+'</tbody></table>'+(!entries.length?'<p class="asw-empty">'+(q?'没有匹配字段。':'请配置两张表中需要比较的字段。')+'</p>':'')+'</div><div class="asw-pager"><span>共 <strong>'+entries.length+'</strong> 个字段</span><div>'+B('上一页',editor?'asw-editor-page':'asw-field-page','sm','data-step="-1" '+(page===1?'disabled':''))+'<span>第 '+page+' / '+pages+' 页</span>'+B('下一页',editor?'asw-editor-page':'asw-field-page','sm','data-step="1" '+(page===pages?'disabled':''))+'</div></div>';}
function aswParameterSummary(g){return '<div class="asw-parameter-summary"><span>完全一致 <strong>＞'+E(g.full)+'</strong> 分</span><span>不完全一致 <strong>≥'+E(g.partial)+'</strong> 分</span><span>'+(g.mode==='batch'?'批量比较 · 每行最多 <strong>'+E(g.perRow)+'</strong> 对':'标准比较')+'</span></div>';}
function aswPanel(){const c=aswConfig(),g=c.association,locked=!!currentTask();return '<aside class="config asw-config"><div class="asw-panel-head"><h2><span class="tw-step">'+(locked?'执行配置':'Step 2')+'</span> 对应字段与比较规则</h2>'+'</div>'+aswPrompt(c,locked)+'<p class="asw-intro">确认两表中哪些字段对应，再开始比较。</p>'+aswParameterSummary(g)+'<div class="asw-fields-toolbar"><strong>比较字段 <span>'+g.rows.length+'</span></strong><div class="search"><input id="asw-field-query" data-asw-input="fields" aria-label="查找比较字段" placeholder="查找比较字段" value="'+E(aswView.query)+'"></div>'+B(locked?'查看完整规则':'调整字段与规则','v2-association','soft sm')+'</div><div id="asw-field-list" class="asw-field-list">'+aswFieldRows(g)+'</div></aside>';}
configPanel=function(){return aswActive()?aswPanel():aswBase.configPanel();};
workbench=function(){if(!aswPreparing())return aswBase.workbench();return '<div class="ew-workspace asw-workspace">'+twHeader()+'<nav class="asw-mobile">'+B('两张台账','asw-panel',aswView.panel==='materials'?'active':'','data-panel="materials"')+B('比较字段与规则','asw-panel',aswView.panel==='config'?'active':'','data-panel="config"')+'</nav><div class="asw-layout" data-asw-panel="'+aswView.panel+'">'+aswMaterials()+aswPanel()+'</div></div>';};
twMountPreview=function(){if(aswPreparing())return;return aswBase.twMountPreview();};
function aswEditor(){const g=editorDraft,locked=!!currentTask(),tab=aswView.editorTab,weight=g.rows.reduce((n,r)=>n+(+r.weight||0),0);let body=aswTabs([['fields','字段与评分'],['decision','判定与比较范围'],['hard','优先判定规则']],tab,'asw-editor-tab');if(tab==='fields')body+='<div class="asw-editor-toolbar"><span>权重合计 <strong>'+weight.toFixed(2)+'</strong> / 1</span><input data-asw-input="editor-fields" aria-label="查找待编辑字段" placeholder="查找比较字段" value="'+E(aswView.editorQuery)+'">'+(!locked?B('恢复提示词字段','v4-reset-mapping','sm')+B('新增字段','asw-add-field','soft sm'):'')+'</div><div id="asw-editor-field-list" class="asw-editor-field-list">'+aswFieldRows(g,true)+'</div>';if(tab==='decision')body+='<div class="asw-parameter-fields"><section><h3>按加权总分判断（0–5分）</h3><div class="asw-form-grid"><label>完全一致：总分严格大于'+editInput('full',g.full,{type:'number',min:0,max:5,step:'.1',readonly:locked})+'</label><label>不完全一致：总分大于等于'+editInput('partial',g.partial,{type:'number',min:0,max:5,step:'.1',readonly:locked})+'</label><label>预筛至少满足几个字段'+editInput('minFields',g.minFields,{type:'number',min:1,max:g.rows.length,readonly:locked})+'</label></div><p>先按字段条件预筛，再按评分判断。预筛参数与最终分数分别设置。</p></section><section><h3>比较范围</h3><label class="asw-mode-field">比较模式'+editSelect('mode',g.mode,[['standard','标准模式'],['batch','批量模式']],locked)+'</label><p>标准模式逐行比较；批量模式先筛选候选，达到上限后会截断，未返回记录不能认定为无关联。</p>'+(g.mode==='batch'?'<div class="asw-form-grid"><label>表一每行最多比较（1–20对）'+editInput('perRow',g.perRow,{type:'number',min:1,max:20,readonly:locked})+'</label><label>本次最多比较（1000–50000对）'+editInput('total',g.total,{type:'number',min:1000,max:50000,step:1000,readonly:locked})+'</label></div>':'')+'</section><section><h3>锁定已匹配记录</h3><p>锁定后不再将相应记录与其他候选继续配对。</p><div class="asw-lock-grid">'+[['full','完全一致时锁定'],['partial','不完全一致时锁定'],['table1','表一完全一致时锁定'],['table2','表二完全一致时锁定']].map(([key,label])=>'<label><input type="checkbox" data-edit="locks.'+key+'" '+(g.locks[key]?'checked':'')+' '+(locked?'disabled':'')+'>'+label+'</label>').join('')+'</div></section><section><label>补充比较要求'+editText('additional',g.additional,locked)+'</label></section></div>';if(tab==='hard')body+='<p class="asw-intro">条件满足时，优先按规则给出判定。支持单个条件或同时满足多个条件。</p>'+hardRulesEditor(g,locked).replaceAll('硬规则','优先判定规则');body+='<div id="editor-error" class="error" role="alert"></div>';return modalFrame(locked?'本次两表比较规则':'调整字段与规则','字段、评分和优先判定规则随本次分析保存。',body,editorFooter(),'asw-editor-dialog');}
mappingEditor=function(two){return two&&aswActive()?aswEditor():aswBase.mappingEditor(two);};
function aswFieldModal(p){const locked=!!currentTask()||p.viewOnly,r=p.draft,w=aswData(),columns=slot=>['请选择',...(file(w['table'+slot])?.columns||[])],field=(key,label,content)=>'<label><span>'+label+'</span>'+content.replaceAll('data-edit=', 'data-asw-edit=')+'</label>';const body='<div class="asw-form-grid">'+field('name','比较内容',editInput('name',r.name,{readonly:locked}))+field('a','表一 · '+E(w.tableAName),editSelect('a',r.a,columns('A'),locked))+field('b','表二 · '+E(w.tableBName),editSelect('b',r.b,columns('B'),locked))+field('type','比较方式',editSelect('type',r.type,COMPARE_TYPES.filter(q=>q[0]!=='investment_gt'),locked))+field('threshold','预筛参数（0–5）',editInput('threshold',r.threshold,{type:'number',min:0,max:5,step:'.01',readonly:locked}))+field('weight','评分权重（0–1）',editInput('weight',r.weight,{type:'number',min:0,max:1,step:'.05',readonly:locked}))+'</div><p class="asw-intro">预筛决定哪些记录进入比较；评分规则决定该字段如何计0–5分。金额需核对两列单位。</p><label class="asw-score-rule"><span>评分规则</span>'+editText('rule',r.rule,locked).replace('data-edit=','data-asw-edit=')+'</label><p id="asw-field-error" class="error" role="alert"></p>';return modalFrame(locked?'查看字段与评分':'编辑比较字段','',body,B(locked?'关闭':'取消','asw-field-cancel')+(locked?'':(p.index>=0?B('移除字段','asw-field-delete','danger ghost'):'')+B('应用字段','asw-field-save','primary')),'asw-field-dialog');}
configurationFragment=function(id,c){const fragment=aswBase.configurationFragment(id,c);if(id!=='association')return fragment;const g=c.association,w=currentTask()?.config===c?currentTask():ws('association'),cfg=fragment.compare_config;cfg.table1_fields=[...new Set(g.rows.map(r=>r.a))];cfg.table2_fields=[...new Set(g.rows.map(r=>r.b))];cfg.logical_field_mapping=Object.fromEntries(g.rows.map(r=>[r.key,[r.a,r.b]]));cfg.complete_field_mapping=Object.fromEntries(g.rows.map(r=>[r.a,r.b]));cfg.table1_numeric_fields=[...new Set(g.rows.filter(r=>r.type==='investment_diff').map(r=>r.a))];cfg.table2_numeric_fields=[...new Set(g.rows.filter(r=>r.type==='investment_diff').map(r=>r.b))];cfg.table1_source_columns=[...(file(w.tableA)?.columns||[])];cfg.table2_source_columns=[...(file(w.tableB)?.columns||[])];fragment.table1={file_uuid:w.tableA,filename:file(w.tableA)?.name||''};fragment.table2={file_uuid:w.tableB,filename:file(w.tableB)?.name||''};fragment.table_labels={table1:w.tableAName,table2:w.tableBName};return fragment;};
const ASW_SYSTEM_KEYS=new Set(['ctid','source_file','match_type','_row_meta','_sourceTable','_rawItem','_pairIndex','doc','other','refs','file_uuid','file_name','组序号','序号','文件名称','说明']);
function aswObject(value,doc){if(Array.isArray(value))return Object.fromEntries(value.map((v,i)=>[file(doc)?.columns?.[i]||'字段'+(i+1),v]));return value&&typeof value==='object'?Object.fromEntries(Object.entries(value).filter(([k])=>!ASW_SYSTEM_KEYS.has(k))):value===undefined?{}:{内容:value};}
function aswClass(type){const text=String(type||'');if(/不完全|部分一致|partial/.test(text))return 'partial';if(/完全一致|完全匹配|编码匹配|full_match/.test(text))return 'full';if(/table1_unique|uniqueA|表一独有/.test(text))return 'uniqueA';if(/table2_unique|uniqueB|表二独有/.test(text))return 'uniqueB';return 'candidate';}
function aswRawPayload(t){let raw=t.associationResult||t.disposal_result||t.DISPOSAL_RESULT||t.compare_response;if(!raw&&!Array.isArray(t.result))raw=t.result;if(typeof raw==='string'){try{raw=JSON.parse(raw);}catch{return null;}}return raw?.compare_response||raw;}
function aswExplicitRefs(raw){return [...new Set([raw?.file_uuid,...(Array.isArray(raw?.refs)?raw.refs:[])].filter(Boolean).map(id=>typeof id==='object'?id.file_uuid||id.id:id).filter(Boolean))];}
function aswNormalize(t){const payload=aswRawPayload(t),rows=[];
 if(payload&&Array.isArray(payload.comparison_results)){const sequences={full:0,partial:0,candidate:0};payload.comparison_results.forEach((r,i)=>{if(/遗漏/.test(String(r.match_type||'')))return;const category=aswClass(r.match_type);rows.push({raw:r,key:'pair:'+i,doc:r.doc||r.file_uuid||t.tableA,other:r.other||t.tableB,refs:aswExplicitRefs(r),a:aswObject(r.table1_item,t.tableA),b:aswObject(r.table2_item,t.tableB),category,match:r.match_type||'关联候选',score:r.weighted_score??r.total_score??r.score,reason:r.reason||r.detail||'',group:++sequences[category]});});for(const [list,key,doc] of [['table1_unique_items','uniqueA',t.tableA],['table2_unique_items','uniqueB',t.tableB]])(payload[list]||[]).forEach((r,i)=>rows.push({raw:r,key:key+':'+i,doc:r.doc||r.file_uuid||doc,other:null,refs:aswExplicitRefs(r),a:key==='uniqueA'?aswObject(r,doc):{},b:key==='uniqueB'?aswObject(r,doc):{},category:key,match:key==='uniqueA'?'表一独有':'表二独有',score:null,reason:'',group:i+1}));return rows;}
 if(payload&&['yz','bwqyz','ggdyxm','tzxmzxsp'].some(key=>Array.isArray(payload[key]))){for(const [section,category] of [['yz','full'],['bwqyz','partial']]){const groups=new Map();for(const r of payload[section]||[]){const key=String(r.组序号);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}for(const [key,pair] of groups){const first=pair.find(r=>r._sourceTable==='table1')||pair[0],second=pair.find(r=>r._sourceTable==='table2')||pair[1];if(!first||!second)continue;rows.push({raw:pair,key:section+':'+key,doc:first.file_uuid||t.tableA,other:second.file_uuid||t.tableB,refs:pair.flatMap(aswExplicitRefs),a:aswObject(first._rawItem||Object.fromEntries(Object.entries(first).filter(([k])=>!['组序号','序号','文件名称','说明'].includes(k))),t.tableA),b:aswObject(second._rawItem||Object.fromEntries(Object.entries(second).filter(([k])=>!['组序号','序号','文件名称','说明'].includes(k))),t.tableB),category,match:category==='full'?'完全一致':'不完全一致',score:first.score??first.评分,reason:first.说明||'',group:+key});}}for(const [section,category,doc] of [['ggdyxm','uniqueA',t.tableA],['tzxmzxsp','uniqueB',t.tableB]])(payload[section]||[]).forEach((r,i)=>rows.push({raw:r,key:section+':'+i,doc:r.file_uuid||doc,other:null,refs:aswExplicitRefs(r),a:category==='uniqueA'?aswObject(r._rawItem||r,doc):{},b:category==='uniqueB'?aswObject(r._rawItem||r,doc):{},category,match:category==='uniqueA'?'表一独有':'表二独有',score:null,reason:'',group:i+1}));return rows;}
 return(Array.isArray(t.result)?t.result:[]).map((r,i)=>{const category=aswClass(r.match_type||r.category),doc=r.doc||r.file_uuid||(category==='uniqueB'?t.tableB:t.tableA);return {raw:r,key:'row:'+i,doc,other:category.startsWith('unique')?null:r.other??t.tableB,refs:aswExplicitRefs(r),a:category==='uniqueB'?{}:aswObject(r.a??r.table1_item,t.tableA),b:category==='uniqueA'?{}:aswObject(r.b??r.table2_item,t.tableB),category,match:r.match_type||r.judgment||(category==='uniqueA'?'表一独有':category==='uniqueB'?'表二独有':'关联候选'),score:r.score??r.weighted_score,reason:r.detail||r.reason||'',group:i+1};});
}
function aswReadable(t,r,download=false){const expected=r.category==='uniqueB'?t.tableB:t.tableA,ids=[...new Set([r.doc,r.other,...(r.refs||[])].filter(Boolean))],scope=new Set([t.tableA,t.tableB]);return r.doc===expected&&(!r.other||r.other===t.tableB)&&ids.length>0&&ids.every(id=>{const d=file(id),p=d&&!d.deleted&&auditFileAccess(d);return scope.has(id)&&p&&p.read&&(!download||p.download);});}

function aswRV(t){if(!aswResultViews.has(t.id)){if(aswResultViews.size>=24)aswResultViews.delete(aswResultViews.keys().next().value);aswResultViews.set(t.id,{query:'',category:'all',page:1,size:20,kept:null,filterPrompt:'',filterReasons:{},busy:false});}return aswResultViews.get(t.id);}
function aswVisible(t,download=false){const v=aswRV(t),q=v.query.toLowerCase().trim();return aswNormalize(t).filter(r=>aswReadable(t,r,download)&&(v.kept===null||r.category.startsWith('unique')||v.kept.includes(r.key))&&(v.category==='all'||r.category===v.category)&&(!q||[r.match,r.reason,...Object.values(r.a),...Object.values(r.b)].map(aswText).join(' ').toLowerCase().includes(q)));}
function aswSummary(record){const entries=Object.entries(record);return entries.length?'<strong>'+E(aswText(entries[0][1]))+'</strong>'+entries.slice(1,3).map(([k,v])=>'<small>'+E(k)+'：'+E(aswText(v))+'</small>').join(''):'<span class="asw-unpaired">—</span>';}
function aswResultTable(t){const v=aswRV(t),rows=aswVisible(t),pages=Math.max(1,Math.ceil(rows.length/v.size));v.page=Math.max(1,Math.min(v.page,pages));return '<div class="asw-result-scroll"><table class="asw-table asw-result-table"><thead><tr><th>'+E(t.tableAName||'表一')+'</th><th>'+E(t.tableBName||'表二')+'</th><th>比较结果</th><th>核验</th></tr></thead><tbody>'+rows.slice((v.page-1)*v.size,v.page*v.size).map(r=>'<tr><td>'+aswSummary(r.a)+'</td><td>'+aswSummary(r.b)+'</td><td>'+tag(E(r.match),r.category==='partial'?'amber':r.category==='full'?'green':'blue')+'<small>'+((r.score!==null&&r.score!==undefined&&Number.isFinite(+r.score))?'评分 '+E(r.score)+' / 5':'')+'</small><div class="asw-two-lines">'+E(r.reason)+'</div></td><td>'+A('查看源行','asw-result-detail','data-key="'+E(r.key)+'"')+'</td></tr>').join('')+'</tbody></table>'+(!rows.length?'<p class="asw-empty">没有匹配结果，可调整筛选条件。</p>':'')+'</div><div class="asw-pager"><span>当前 <strong>'+rows.length+'</strong> 条结果</span><label>每页 <select data-asw-change="result-size" aria-label="每页结果数">'+[20,50,100].map(n=>'<option value="'+n+'" '+(n===v.size?'selected':'')+'>'+n+'</option>').join('')+'</select> 条</label><div>'+B('上一页','asw-result-page','sm','data-step="-1" '+(v.page===1?'disabled':''))+'<span>第 '+v.page+' / '+pages+' 页</span>'+B('下一页','asw-result-page','sm','data-step="1" '+(v.page===pages?'disabled':''))+'</div></div>';}
resultContent=function(t){if(t.toolId!=='association')return aswBase.resultContent(t);const v=aswRV(t),all=aswNormalize(t).filter(r=>aswReadable(t,r)),groups=[['all','全部结果'],['full','完全一致'],['partial','不完全一致'],['uniqueA','表一独有'],['uniqueB','表二独有'],['candidate','关联候选']].filter(([key])=>key==='all'||all.some(r=>r.category===key));return '<section class="asw-results"><div class="asw-results-head"><h2>两表比较结果</h2><div>'+B('进一步筛选','refine','sm',v.busy?'disabled':'')+(v.kept!==null?B('恢复全部结果','restore-candidates','sm'):'')+'</div></div><p class="asw-result-intro">'+E(t.tableAName||'表一')+' ↔ '+E(t.tableBName||'表二')+' · 关联候选需结合立项、资金等资料核验。</p>'+aswTabs(groups.map(([key,name])=>[key,name+' <strong>'+(key==='all'?all.length:all.filter(r=>r.category===key).length)+'</strong>']),v.category,'asw-result-category','category')+'<div class="asw-result-tools"><div class="search"><input id="asw-result-query" data-asw-input="results" aria-label="查找两表结果" placeholder="查找项目、单位或比较说明" value="'+E(v.query)+'"></div>'+A('重置','asw-result-reset')+'<span>导出保留当前筛选结果。</span></div>'+(v.kept!==null?'<p class="asw-refined-note">已按要求筛选配对结果，独有记录保留。'+A('查看筛选要求','refine')+'</p>':'')+'<div id="asw-result-list">'+aswResultTable(t)+'</div><p class="asw-result-footnote">仅展示实际返回的结果；未返回的项目不等于无关联。</p></section>';};
function aswRecordMarkup(name,record,doc){return '<section class="asw-record"><h3>'+E(name)+'</h3><p>'+E(file(doc)?.name||'原资料已移除')+'</p><dl>'+Object.entries(record).map(([k,v])=>'<dt>'+E(k)+'</dt><dd>'+E(aswText(v))+'</dd>').join('')+'</dl></section>';}
modalContent=function(){if(!aswActive())return aswBase.modalContent();if(modal==='asw-field')return aswFieldModal(modalData);if(modal==='asw-result-detail'){const t=currentTask(),r=aswNormalize(t).find(r=>r.key===modalData.key);if(!r||!aswReadable(t,r))return modalFrame('无法查看来源','','来源已移除或没有查看权限。',B('关闭','close-modal'),'medium');return modalFrame('核对两表来源记录',E(r.match),'<div class="asw-detail-summary">'+(r.score!==undefined&&r.score!==null?'<strong>评分 '+E(r.score)+' / 5</strong>':'')+'<p>'+E(r.reason||'本条未返回比较说明。')+'</p>'+(aswRV(t).filterReasons[r.key]?'<p>筛选说明：'+E(aswRV(t).filterReasons[r.key])+'</p>':'')+'</div><div class="asw-record-grid">'+(Object.keys(r.a).length?aswRecordMarkup(t.tableAName||'表一',r.a,t.tableA):'')+(Object.keys(r.b).length?aswRecordMarkup(t.tableBName||'表二',r.b,t.tableB):'')+'</div><p class="asw-intro">以上为本条结果对应的来源行，保留原始字段及单位。</p>',B('关闭','close-modal'),'asw-evidence-dialog');}if(modal==='asw-refine'){const v=aswRV(currentTask());return modalFrame('进一步筛选结果','仅筛选当前任务返回的配对组，表一和表二独有记录保留。','<label class="field"><span>筛选要求</span><textarea id="asw-refine-prompt" rows="5" placeholder="例如：保留评分不低于4分的配对。">'+E(modalData.prompt??v.filterPrompt)+'</textarea></label><div class="asw-filter-example">'+A('填入评分筛选示例','asw-refine-example')+'</div><p id="asw-refine-error" class="error" role="alert"></p>',B('取消','close-modal')+B(v.busy?'筛选中…':'应用筛选','asw-refine-apply','primary',v.busy?'disabled':''),'medium');}return aswBase.modalContent();};
closeModal=function(){if(aswActive()&&modal==='asw-field'&&modalData.parent){const back=modalData.parent;openModal('v2-association',back);return;}return aswBase.closeModal();};
function aswLocalDecisions(rows,prompt){const score=prompt.match(/评分\s*(不低于|大于等于|≥|>=|超过|大于|>|不高于|小于等于|≤|<=|低于|小于|<)\s*(\d+(?:\.\d+)?)/);if(score){const n=+score[2],op=score[1];if(n<0||n>5)throw Error('评分应在0–5分范围内。');return rows.filter(r=>Number.isFinite(+r.score)&&r.score!==null&&r.score!==undefined).map(r=>({key:r.key,keep:['不低于','大于等于','≥','>='].includes(op)?+r.score>=n:['超过','大于','>'].includes(op)?+r.score>n:['不高于','小于等于','≤','<='].includes(op)?+r.score<=n:+r.score<n,reason:prompt}));}const keyword=prompt.match(/(?:包含|含有|关键词[为是：:]?)\s*[“「"']?(.+?)[”」"']?[。.]?$/);if(keyword){const q=keyword[1].replace(/[”」"'。.]$/,'').trim();return rows.map(r=>({key:r.key,keep:JSON.stringify([r.a,r.b,r.reason]).includes(q),reason:prompt}));}throw Error('当前演示可按评分或关键词筛选，例如“保留评分不低于4分的配对”。其他要求需接入分析服务。');}
async function aswRefineApply(){const t=currentTask(),v=aswRV(t),prompt=$('#asw-refine-prompt').value.trim();if(!prompt){$('#asw-refine-error').textContent='请填写筛选要求。';return;}const all=aswNormalize(t).filter(r=>aswReadable(t,r)&&!r.category.startsWith('unique'));if(!all.length){$('#asw-refine-error').textContent='当前没有可筛选的配对组。';return;}v.busy=true;modalData.prompt=prompt;paintModal();try{const fn=window.auditAssociationRefine;let decisions;if(typeof fn==='function'){const response=await fn({task_uuid:t.id,prompt});if(response.status&&response.status!=='success')throw Error(response.message||'筛选失败。');const supplied=Array.isArray(response)?response:response.decisions;if(Array.isArray(supplied))decisions=supplied;else if(supplied&&typeof supplied==='object'){decisions=[];for(const [section,category] of [['yz','full'],['bwqyz','partial']])for(const item of supplied[section]||[]){const row=all.find(r=>r.category===category&&r.group===+item.group_key);if(row)decisions.push({key:row.key,keep:item.keep,reason:item.filter_reason});}}else throw Error('筛选未返回有效配对结果。');}else decisions=aswLocalDecisions(all,prompt);v.kept=all.filter(r=>decisions.some(d=>String(d.key??d.group_key)===r.key&&d.keep===true)).map(r=>r.key);v.filterReasons=Object.fromEntries(decisions.filter(d=>d.keep).map(d=>[String(d.key??d.group_key),d.reason||d.filter_reason||prompt]));v.filterPrompt=prompt;v.page=1;v.busy=false;aswBase.closeModal();render();toast('筛选完成，可恢复全部结果。');}catch(e){v.busy=false;paintModal();$('#asw-refine-error').textContent=e.message;}}
exportRows=function(t,scope='all'){if(t.toolId!=='association')return aswBase.exportRows(t,scope);const rows=aswVisible(t,true).filter(r=>scope==='all'||[r.doc,r.other].includes(scope)),a=[...new Set(rows.flatMap(r=>Object.keys(r.a)))],b=[...new Set(rows.flatMap(r=>Object.keys(r.b)))];return [['比较结果','表一来源',...a.map(k=>(t.tableAName||'表一')+' · '+k),'表二来源',...b.map(k=>(t.tableBName||'表二')+' · '+k),'匹配评分（0–5）','比较说明','筛选说明'],...rows.map(r=>[r.match,Object.keys(r.a).length?file(t.tableA)?.name:'',...a.map(k=>Object.hasOwn(r.a,k)?aswText(r.a[k]):''),Object.keys(r.b).length?file(t.tableB)?.name:'',...b.map(k=>Object.hasOwn(r.b,k)?aswText(r.b[k]):''),r.score??'',r.reason,aswRV(t).filterReasons[r.key]||''])];};
doExport=function(){const t=currentTask();if(t?.toolId!=='association')return aswBase.doExport();if(!trCanDownload(t))return toast('暂无可导出结果，或来源资料权限已变化。');if($('#export-format').value!=='json')return aswBase.doExport();const scope=$('#export-scope').value,rows=aswVisible(t,true).filter(r=>scope==='all'||[r.doc,r.other].includes(scope));download((t.name||'两表比较')+'-结果.json',JSON.stringify({task:t.name,scope,config:t.config,execution_config:t.configFragment,tableA:t.tableA,tableB:t.tableB,tableAName:t.tableAName,tableBName:t.tableBName,filter:{query:aswRV(t).query,category:aswRV(t).category,prompt:aswRV(t).filterPrompt},results:rows.map(r=>({category:r.category,sourceA:Object.keys(r.a).length?t.tableA:null,sourceB:Object.keys(r.b).length?t.tableB:null,result:r.raw,filter_reason:aswRV(t).filterReasons[r.key]||null}))},null,2),'application/json;charset=utf-8');closeModal();};
handleAction=function(action,el){if(!aswActive())return aswBase.handleAction(action,el);const d=el?.dataset||{};
 if(action==='asw-panel'){aswView.panel=d.panel;render();return;}
 if(action==='asw-field-page'){aswView.page+=+d.step;$('#asw-field-list').innerHTML=aswFieldRows();return;}
 if(action==='asw-editor-page'){aswView.editorPage+=+d.step;$('#asw-editor-field-list').innerHTML=aswFieldRows(editorDraft,true);return;}
 if(action==='asw-editor-tab'){aswView.editorTab=d.tab;paintModal();return;}
 if(action==='asw-view-field'){const r=aswConfig().association.rows[+d.index];openModal('asw-field',{draft:structuredClone(r),index:+d.index,viewOnly:true});return;}
 if(action==='asw-edit-field'){openModal('asw-field',{draft:structuredClone(editorDraft.rows[+d.index]),index:+d.index,parent:structuredClone(modalData)});return;}
 if(action==='asw-add-field'&&!currentTask()){const n=Math.max(0,...editorDraft.rows.map(r=>+r.key.slice(1)||0))+1;openModal('asw-field',{draft:{key:'F'+n,name:'',a:'请选择',b:'请选择',type:'similarity',threshold:.8,weight:0,rule:''},index:-1,parent:structuredClone(modalData)});return;}
 if(action==='asw-field-delete'&&modal==='asw-field'&&!currentTask()&&!modalData.viewOnly){const p=modalData,key=editorDraft.rows[p.index]?.key;editorDraft.rows.splice(p.index,1);editorDraft.hardRules=editorDraft.hardRules.filter(r=>!(r.logic==='and'?r.rules:[r]).some(q=>q.field===key));openModal('v2-association',p.parent);return;}
 if(action==='asw-field-cancel'){if(modalData.parent)openModal('v2-association',modalData.parent);else aswBase.closeModal();return;}
 if(action==='asw-field-save'&&modal==='asw-field'&&!currentTask()){const p=modalData,r=p.draft,w=ws(),error=!r.name.trim()||!r.rule.trim()?'请填写比较内容与评分规则。':![r.a,r.b].every(v=>v&&v!=='请选择')?'请对应两张表的实际字段。':!Number.isFinite(+r.threshold)||+r.threshold<0||+r.threshold>5||!Number.isFinite(+r.weight)||+r.weight<0||+r.weight>1?'请检查预筛参数（0–5）及权重（0–1）。':!file(w.tableA)?.columns?.includes(r.a)||!file(w.tableB)?.columns?.includes(r.b)?'所选字段已不在台账表头中，请重新选择。':'';if(error){$('#asw-field-error').textContent=error;return;}if(p.index<0)editorDraft.rows.push(structuredClone(r));else editorDraft.rows[p.index]=structuredClone(r);openModal('v2-association',p.parent);return;}
 if(action==='asw-result-category'){const v=aswRV(currentTask());v.category=d.category;v.page=1;render();return;}
 if(action==='asw-result-page'){aswRV(currentTask()).page+=+d.step;$('#asw-result-list').innerHTML=aswResultTable(currentTask());return;}
 if(action==='asw-result-reset'){const v=aswRV(currentTask());v.query='';v.category='all';v.page=1;render();return;}
 if(action==='asw-result-detail'||action==='result-detail'&&currentTask()){const key=d.key||aswNormalize(currentTask())[+d.index]?.key;openModal('asw-result-detail',{key});return;}
 if(action==='refine'){openModal('asw-refine',{});return;}
 if(action==='asw-refine-example'){$('#asw-refine-prompt').value='保留评分不低于4分的配对。';return;}
 if(action==='asw-refine-apply')return aswRefineApply();
 if(action==='restore-candidates'){const v=aswRV(currentTask());v.kept=null;v.filterPrompt='';v.filterReasons={};v.page=1;render();return;}
 if(aswPreparing()&&['tw-preview','preview'].includes(action))return aswBase.handleAction('source',el);
 if(action==='v2-association'){aswView.editorTab='fields';aswView.editorPage=1;aswView.editorQuery='';}
 return aswBase.handleAction(action,el);
};
window.addEventListener('input',e=>{if(!aswActive())return;const el=e.target,key=el.dataset.aswInput;if(key){e.stopImmediatePropagation();if(key==='fields'){aswView.query=el.value;aswView.page=1;$('#asw-field-list').innerHTML=aswFieldRows();}if(key==='editor-fields'){aswView.editorQuery=el.value;aswView.editorPage=1;$('#asw-editor-field-list').innerHTML=aswFieldRows(editorDraft,true);}if(key==='results'){const v=aswRV(currentTask());v.query=el.value;v.page=1;$('#asw-result-list').innerHTML=aswResultTable(currentTask());}}if(modal==='asw-field'&&el.dataset.aswEdit&&!currentTask()&&!modalData.viewOnly){e.stopImmediatePropagation();modalData.draft[el.dataset.aswEdit]=el.type==='number'?+el.value:el.value;}},true);
window.addEventListener('change',e=>{if(!aswActive())return;const el=e.target;if(el.dataset.aswChange==='result-size'){e.stopImmediatePropagation();const v=aswRV(currentTask());v.size=+el.value;v.page=1;$('#asw-result-list').innerHTML=aswResultTable(currentTask());}if(modal==='asw-field'&&el.dataset.aswEdit&&!currentTask()&&!modalData.viewOnly){e.stopImmediatePropagation();modalData.draft[el.dataset.aswEdit]=el.type==='number'?+el.value:el.value;if(el.dataset.aswEdit==='type'){modalData.draft.threshold=el.value==='investment_diff'?.04:el.value==='exact'?0:.8;paintModal();}}if(modal==='v2-association'&&el.dataset.edit==='mode')setTimeout(()=>{if(modal==='v2-association')paintModal();},0);},true);
render();

const aswBaseOutput=tcOutput;tcOutput=function(t){if(tcResolve(t)!=='association'||!trHasResult(t))return aswBaseOutput(t);const rows=aswNormalize(t).filter(r=>aswReadable(t,r)),paired=rows.filter(r=>!r.category.startsWith('unique')).length,unique=rows.length-paired;const base=aswBaseOutput(t);return {...base,text:paired+' 组配对结果'+(unique?' · '+unique+' 条独有记录':'')};};

const aswBaseCanDownload=trCanDownload;trCanDownload=function(t){if(t?.toolId!=='association')return aswBaseCanDownload(t);return trHasResult(t)&&aswNormalize(t).some(r=>aswReadable(t,r,true))&&[t.tableA,t.tableB].every(id=>{const d=file(id),p=d&&!d.deleted&&auditFileAccess(d);return p&&p.read&&p.download;});};
